insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_tech_v1'
from (values
('126.18.c.1.A',3,'In a flowchart, a diamond shape usually represents a...','["decision", "storage drive", "start of the program", "printout"]'::jsonb,0,'Diamonds ask yes/no questions.','original'),
('126.18.c.1.A',3,'A seventh grader uses a flowchart to break the morning routine into steps. This is an example of...','["compressing a video", "decomposing a real-world problem", "formatting a drive", "encrypting a file"]'::jsonb,1,'Flowcharts show structured parts.','original'),
('126.18.c.1.B',3,'Looking at a flowchart, the arrows show the...','["brightness", "price", "order and direction of the steps", "file size"]'::jsonb,2,'Arrows connect steps in sequence.','original'),
('126.18.c.1.B',3,'If a flowchart loops back to an earlier step, it shows a...','["spelling mistake", "network error", "delete command", "repeating pattern"]'::jsonb,3,'A loop repeats steps.','original'),
('126.18.c.1.C',3,'An algorithm that works for any list of numbers, not only one, is...','["generalized", "deleted", "random", "broken"]'::jsonb,0,'Abstraction lets one algorithm solve many cases.','original'),
('126.18.c.1.C',3,'Abstraction in programming helps because it...','["removes all variables", "hides unnecessary detail so a solution can be reused", "makes every program longer", "prevents testing"]'::jsonb,1,'It simplifies and generalizes.','original'),
('126.18.c.1.D',3,'A team creates a flowchart together so everyone can...','["skip testing", "avoid planning", "see the problem, solution and steps before coding", "write code in secret"]'::jsonb,2,'Shared plans improve teamwork.','original'),
('126.18.c.1.D',3,'Using flowcharts to document a solution helps others to...','["erase the steps", "rewrite it blindly", "ignore the problem", "understand and review the plan"]'::jsonb,3,'Documentation supports collaboration.','original'),
('126.18.c.1.E',3,'A programmer who adds print statements to see the value of a variable while a program runs is using a...','["debugging technique", "naming convention", "formatting rule", "compression tool"]'::jsonb,0,'Printing values helps find errors.','original'),
('126.18.c.1.E',3,'Rubber duck debugging means...','["renaming the program", "explaining your code line by line to find the error", "throwing the computer", "deleting the file"]'::jsonb,1,'Explaining reveals mistakes.','original'),
('126.18.c.1.F',3,'Using iteration instead of writing the same line 100 times makes a program...','["impossible to run", "more likely to crash", "shorter and easier to change", "slower to understand"]'::jsonb,2,'Loops reduce duplication.','original'),
('126.18.c.1.F',3,'A loop that repeats until a condition becomes false is called a...','["jump file", "folder", "cookie", "while loop"]'::jsonb,3,'While loops repeat as long as the condition is true.','original'),
('126.18.c.2.A',3,'Which of these is a data type for whole numbers?','["integer", "character", "string", "Boolean"]'::jsonb,0,'Integers are whole numbers.','original'),
('126.18.c.2.A',3,'Renaming a variable from ''x'' to ''playerHealth'' improves...','["internet speed", "readability", "file size", "battery life"]'::jsonb,1,'Clear names explain the purpose.','original'),
('126.18.c.2.B',3,'A nested loop is a loop...','["after the program ends", "that never runs", "inside another loop", "outside the code"]'::jsonb,2,'Nested loops repeat inner steps for each outer repeat.','original'),
('126.18.c.2.B',3,'A software design process generally includes planning, coding, testing and...','["ignoring", "deleting", "hiding", "revising"]'::jsonb,3,'Iteration improves programs.','original'),
('126.18.c.3.A',3,'A student who sets a goal to finish a prototype by Friday and checks progress daily is using...','["goal setting to solve design challenges", "guessing", "luck", "avoidance"]'::jsonb,0,'Goals guide progress.','original'),
('126.18.c.3.A',3,'A trait such as curiosity helps a designer by...','["ending the project", "driving them to explore new solutions", "stopping progress", "creating confusion"]'::jsonb,1,'Curiosity fuels innovation.','original'),
('126.18.c.3.B',3,'The planning stage of a design process includes...','["deleting ideas", "publishing immediately", "selecting digital tools and mapping steps", "skipping research"]'::jsonb,2,'Planning chooses tools and approach.','original'),
('126.18.c.3.B',3,'After testing a digital design, a team should...','["ignore the results", "start over without learning", "cancel the project", "make improvements based on feedback"]'::jsonb,3,'Revision follows testing.','original'),
('126.18.c.3.C',3,'Which industry uses a design process to create products?','["video game development", "none", "only farming", "only banking"]'::jsonb,0,'Games are designed, tested and revised.','original'),
('126.18.c.3.C',3,'An engineer designing a bridge uses a design process by...','["skipping safety checks", "planning, testing models and improving the design", "building first", "guessing"]'::jsonb,1,'Design steps apply across fields.','original'),
('126.18.c.4.A',3,'Explain how smartphones changed society: they allowed people to...','["stop using maps", "lose internet", "access information and communicate anywhere", "avoid all technology"]'::jsonb,2,'Mobile tech changed daily life.','original'),
('126.18.c.4.A',3,'The shift from paper maps to GPS affected travel by...','["removing roads", "making travel impossible", "stopping cars", "making navigation faster and easier"]'::jsonb,3,'GPS technology changed how people travel.','original'),
('126.18.c.4.B',3,'A global trend like increased online shopping has influenced technology by...','["growing delivery tracking and payment systems", "banning shipping", "removing websites", "ending credit cards"]'::jsonb,0,'Trends shape tools.','original'),
('126.18.c.4.B',3,'Global concern about data privacy has led to...','["no encryption", "stronger security and privacy settings", "open access to all data", "fewer passwords"]'::jsonb,1,'Public concern shapes technology.','original'),
('126.18.c.4.C',3,'A student who learned spreadsheet formulas uses that knowledge to learn a new database tool by...','["giving up", "starting from scratch", "applying similar logic to the new tool", "ignoring formulas"]'::jsonb,2,'Transferring knowledge speeds learning.','original'),
('126.18.c.4.C',3,'When facing new software, relying on what you already know about menus and shortcuts is...','["plagiarism", "a mistake", "a virus", "transferring knowledge"]'::jsonb,3,'Prior experience helps.','original'),
('126.18.c.5.A',3,'In binary, the number system used by computers, the only digits are...','["0 and 1", "A and B", "0 through 9", "1 through 10"]'::jsonb,0,'Binary has two digits.','original'),
('126.18.c.5.A',3,'The binary number 101 equals which decimal number?','["3", "5", "10", "7"]'::jsonb,1,'1×4 + 0×2 + 1×1 = 5.','original'),
('126.18.c.5.B',3,'To search for results that exclude a word, you can use the Boolean operator...','["ALSO", "OR", "NOT", "AND"]'::jsonb,2,'NOT removes results with that word.','original'),
('126.18.c.5.B',3,'Limiting a search to a certain date range or site type is called using...','["shortcuts", "bookmarks", "file extensions", "search filters"]'::jsonb,3,'Filters narrow results.','original'),
('126.18.c.6',3,'In a spreadsheet, a cell range such as B2:B10 refers to...','["the cells from B2 down to B10", "only B2", "a chart", "only B10"]'::jsonb,0,'Ranges cover several cells.','original'),
('126.18.c.6',3,'Sorting data from smallest to largest is called...','["reverse alphabet only", "ascending order", "random order", "descending order"]'::jsonb,1,'Ascending goes low to high.','original'),
('126.18.c.7',3,'To publish survey results clearly, a student might use a...','["wall of numbers", "blank slide", "chart with labeled axes", "unlabeled graph"]'::jsonb,2,'Labels make data clear.','original'),
('126.18.c.7',3,'A good way to communicate data to a general audience is to...','["hide the source", "use tiny text", "use only jargon", "present a short summary with a clear visual"]'::jsonb,3,'Clarity helps audience understanding.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Technology Applications' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
